package netdiag

import (
	"context"
	"fmt"
	"log"
	"net"
	"net/netip"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/engine"
	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/netiface"
	"github.com/anthnel/devdesk/internal/nettrace"
)

// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
// resolved message and the done message. The producer therefore never waits
// for a reader. Contract: resolved now carries source and ctr but is still one
// message, so 1 resolved + MaxHopsLimit (30) hops + 1 done = 32 = pathChanCap,
// and sendDone never evicts resolved with the real engine.
const pathChanCap = nettrace.MaxHopsLimit + 2

// pathEngine is the seam between the path tab and the network: tests replace
// it with a fake.
type pathEngine struct {
	supported func() error
	resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
	route     func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error)
	trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)

	engineName func() string                                                            // engine.Current().Name
	engineOS   func(ctx context.Context) (string, error)                                // docker.EngineOperatingSystem
	running    func(ctx context.Context) ([]docker.Container, error)                    // running containers only
	inspect    func(ctx context.Context, id string) (docker.ContainerNetworking, error) // read-only
	network    func(ctx context.Context, id string) (docker.NetworkBridge, error)       // docker.InspectNetworkBridge
	interfaces func(ctx context.Context) ([]netiface.Interface, error)                  // netiface.List
}

// systemPathEngine returns the engine backed by the real resolver and sockets.
func systemPathEngine() pathEngine {
	env := netcheck.SystemEnv(netcheck.DefaultSettings())
	return pathEngine{
		supported: nettrace.Supported,
		resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
			return net.DefaultResolver.LookupNetIP(ctx, "ip4", host)
		},
		route: func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error) {
			return env.Route(ctx, net.IP(a.AsSlice()))
		},
		trace:      nettrace.TraceEach,
		engineName: func() string { return engine.Current().Name },
		engineOS:   docker.EngineOperatingSystem,
		running: func(ctx context.Context) ([]docker.Container, error) {
			return docker.ListContainersContext(ctx, false)
		},
		inspect:    docker.InspectContainerNetworking,
		network:    docker.InspectNetworkBridge,
		interfaces: netiface.List,
	}
}

// pathResolvedMsg reports the address the target resolved to.
type pathResolvedMsg struct {
	gen      int
	addr     netip.Addr
	route    netcheck.RouteHop
	routeErr error
	source   pathSource                 // the source at launch
	ctr      docker.ContainerNetworking // zero for this machine
	ctrErr   error                      // logged by the producer, never shown
	bridge   pathBridge                 // what is known of the container network's host interface
}

// pathSourcesMsg carries what the selector offers once the engine answered.
type pathSourcesMsg struct {
	gen  int // the request it answers, so a stale answer can be dropped
	list pathSourceList
}

// loadPathSourcesCmd reads the selector's list off the Update goroutine, under
// its own timeout so a hung engine cannot keep the selector loading. It
// touches no model (Rule 110): the answer comes back as a message.
func loadPathSourcesCmd(gen int, timeout time.Duration, e pathEngine) tea.Cmd {
	return func() tea.Msg {
		return pathSourcesMsg{gen: gen, list: listPathSourcesUnder(context.Background(), timeout, e)}
	}
}

// listPathSourcesUnder reads the list under a timeout derived from parent.
// Only parent decides whether an error is logged: a deadline exceeded on its
// own is a real failure, a canceled parent is not.
func listPathSourcesUnder(parent context.Context, timeout time.Duration, e pathEngine) pathSourceList {
	ctx, cancel := context.WithTimeout(parent, timeout)
	defer cancel()
	return readPathSources(parent, ctx, e)
}

// listPathSources reads what the selector offers with a single context.
func listPathSources(ctx context.Context, e pathEngine) pathSourceList {
	return readPathSources(ctx, ctx, e)
}

// readPathSources reads what the selector offers. Only read-only engine calls
// are made (info, ps): nothing starts or enters a container. A raw error goes
// to the log, never to the note, unless parent was canceled.
func readPathSources(parent, ctx context.Context, e pathEngine) pathSourceList {
	name := ""
	if e.engineName != nil {
		name = e.engineName()
	}
	if name != "docker" { // podman: no exec at all
		return sourceListFrom(name, "", nil, nil, nil)
	}
	osName, osErr := e.engineOS(ctx)
	if osErr != nil {
		logSourcesError(parent, osErr)
		return sourceListFrom(name, "", osErr, nil, nil)
	}
	if isDockerDesktop(osName) {
		return sourceListFrom(name, osName, nil, nil, nil)
	}
	cs, psErr := e.running(ctx)
	if psErr != nil {
		logSourcesError(parent, psErr)
	}
	return sourceListFrom(name, osName, nil, cs, psErr)
}

// logSourcesError logs a read failure unless the caller gave up (parent is
// the context received, not the one bounded by the timeout).
func logSourcesError(parent context.Context, err error) {
	if parent.Err() == nil {
		log.Printf("ERROR [netdiag/path] sources: %v", err)
	}
}

// pathHopMsg carries one hop as the engine reports it.
type pathHopMsg struct {
	gen int
	hop nettrace.Hop
}

// pathDoneMsg ends a run: a result, or an error when no trace happened.
type pathDoneMsg struct {
	gen    int
	result nettrace.Result
	err    error
}

// producePath resolves the target, traces it and sends the messages to out,
// then closes out. It runs inside a Cmd and touches no model (Rule 110).
// out must have room for pathChanCap messages: sends never block, so a view
// that stops reading after canceling leaks nothing.
func producePath(ctx context.Context, gen int, tg pathTarget, src pathSource, resolveTimeout time.Duration, e pathEngine, out chan tea.Msg) {
	defer close(out)
	send := func(m tea.Msg) {
		select {
		case out <- m:
		default:
		}
	}
	// sendDone must never be lost: when the channel is full the oldest message
	// is dropped to make room. The producer is the only sender, so one drop
	// frees a slot for good.
	sendDone := func(m tea.Msg) {
		for range 2 {
			select {
			case out <- m:
				return
			default:
			}
			select {
			case <-out:
			default:
			}
		}
	}

	addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
	if err != nil {
		if ctx.Err() == nil { // esc during the resolution is not an error
			log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
		}
		sendDone(pathDoneMsg{gen: gen, err: err})
		return
	}
	// The route is asked for the address actually traced. A failure is not
	// fatal and is never shown: the trace goes on without the route column.
	route, routeErr := e.route(ctx, addr)
	if routeErr != nil && ctx.Err() == nil {
		log.Printf("ERROR [netdiag/path] route %s: %v", tg.Host, routeErr)
	}
	ctr, ctrErr := inspectPathSource(ctx, src, resolveTimeout, e)
	var bridge pathBridge
	if ctrErr == nil && !src.isHost() {
		bridge = readPathBridge(ctx, ctr, resolveTimeout, e)
	}
	send(pathResolvedMsg{gen: gen, addr: addr, route: route, routeErr: routeErr, source: src, ctr: ctr, ctrErr: ctrErr, bridge: bridge})

	res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
		send(pathHopMsg{gen: gen, hop: h})
	})
	if err != nil {
		log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
	}
	sendDone(pathDoneMsg{gen: gen, result: res, err: err})
}

// inspectPathSource reads the chosen container's network under its own
// timeout. This machine reads nothing. A failure is not fatal and is never
// shown: the raw error goes to the log unless the run was canceled.
func inspectPathSource(ctx context.Context, src pathSource, timeout time.Duration, e pathEngine) (docker.ContainerNetworking, error) {
	if src.isHost() {
		return docker.ContainerNetworking{}, nil
	}
	ictx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	ctr, err := e.inspect(ictx, src.ID)
	if err != nil && ctx.Err() == nil {
		log.Printf("ERROR [netdiag/path] inspect %s: %v", src.ID, err)
	}
	return ctr, err
}

// resolvePathTarget returns the IPv4 address to trace: a literal is used as
// is, a name is resolved under its own timeout.
func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
	if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
		return a, nil
	}
	rctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	addrs, err := e.resolve(rctx, host)
	if err != nil {
		return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
	}
	if len(addrs) == 0 {
		return netip.Addr{}, errPathNoIPv4
	}
	return addrs[0], nil
}

// waitForPathMsg returns a Cmd that yields the next message of in, or nil
// once in is closed. The view re-arms it after every message.
func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
	return func() tea.Msg {
		m, ok := <-in
		if !ok {
			return nil
		}
		return m
	}
}

package netdiag

import (
	"context"
	"net/netip"
	"time"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/nettrace"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	// reasonPathUnsupported is shown when the platform cannot trace a path. The
	// header greys enter out and the handler refuses with the same text.
	reasonPathUnsupported = "The path trace is not supported on this platform"

	// defaultPathResolveTimeout bounds the name resolution of a target.
	defaultPathResolveTimeout = 5 * time.Second

	// pathInputCharLimit holds a 253-character host name, a colon and a port.
	pathInputCharLimit = 262
)

// pathState is where the Path tab is in its life cycle.
type pathState int

const (
	// pathEditing: the target field has the keyboard.
	pathEditing pathState = iota
	// pathRunning: a trace is in flight; the field is blurred.
	pathRunning
	// pathDone: a trace ended (or was canceled); the hops stay on screen.
	pathDone
)

// PathModel is the Path tab: a target field above a table of hops that fills
// in while the trace runs.
type PathModel struct {
	width  int
	height int

	engine         pathEngine
	resolveTimeout time.Duration

	input textinput.Model
	table datatable.Model[pathStep]

	state  pathState
	target pathTarget
	addr   netip.Addr
	// route is the way out of this machine; nil until the resolved message.
	route *pathRoute
	// hops is what the engine reported so far; the table shows
	// visiblePathHops(hops). At done it is replaced by Result.Hops.
	hops   []nettrace.Hop
	result *nettrace.Result
	// errText is the persistent footer error of a run that never traced. It is
	// cleared by a change of the field or by the next launch, not by a timer.
	errText string

	// gen identifies the run whose messages are accepted; cancel and msgs
	// belong to that run.
	gen    int
	cancel context.CancelFunc
	msgs   <-chan tea.Msg

	footer components.FooterMessage

	// source is where the trace starts: this machine, or a running container
	// (DEVDESK-330). picker is the open selector, nil when closed; sourcesGen
	// identifies the listing whose answer it accepts; container is what the
	// column says about the source of the current run.
	source     pathSource
	picker     *pathSourcePicker
	sourcesGen int
	container  *pathContainer
}

// pathSourceKey opens the "Trace from" selector (declared exception, surface
// netdiag/path).
const pathSourceKey = "ctrl+o"

// pickerOpen reports whether the selector holds the keyboard.
func (pm *PathModel) pickerOpen() bool { return pm.picker != nil }

func newPathModel(e pathEngine) *PathModel {
	in := textinput.New()
	theme.StyleTextInput(&in)
	in.Placeholder = "hostname or IPv4 address[:port]"
	in.CharLimit = pathInputCharLimit
	in.Focus()

	return &PathModel{
		engine:         e,
		resolveTimeout: defaultPathResolveTimeout,
		input:          in,
		table: datatable.New(datatable.Config[pathStep]{
			Columns:    pathColumns(),
			SortColumn: -1, // the path order is the content
		}),
	}
}

// InEditMode reports whether the target field has the keyboard.
// The open selector holds the keyboard too, from any state.
func (pm *PathModel) InEditMode() bool { return pm.state == pathEditing || pm.pickerOpen() }

func (pm *PathModel) running() bool { return pm.state == pathRunning }

func (pm *PathModel) resize(width, height int) {
	pm.width = width
	pm.height = max(height, 3)
	pm.input.SetWidth(max(width-ansi.StringWidth(pathBarLabel)-4, 10))
	pm.table.Resize(width, pm.height)
}

// launchable is the one answer to "can a trace start here", read by the header
// and by the handler (Rule 130).
func (pm *PathModel) launchable() shortcut.Availability {
	if pm.engine.supported() != nil {
		return shortcut.Unavailable(reasonPathUnsupported)
	}
	return shortcut.Availability{}
}

func (pm *PathModel) update(msg tea.Msg) (*PathModel, tea.Cmd) {
	switch msg := msg.(type) {
	case pathResolvedMsg:
		return pm.handleResolved(msg)
	case pathHopMsg:
		return pm.handleHop(msg)
	case pathDoneMsg:
		return pm.handleDone(msg)
	case pathSourcesMsg:
		return pm.handleSources(msg)
	case tea.KeyPressMsg:
		return pm.handleKey(msg)
	case tea.PasteMsg:
		return pm.handlePaste(msg)
	}
	// Anything else is a footer expiry or the cursor blink of the field: the
	// field needs the blink itself, or its cursor freezes.
	pm.footer.Handle(msg)
	var cmd tea.Cmd
	pm.input, cmd = pm.input.Update(msg)
	return pm, cmd
}

func (pm *PathModel) handleResolved(msg pathResolvedMsg) (*PathModel, tea.Cmd) {
	if msg.gen != pm.gen {
		return pm, nil
	}
	pm.addr = msg.addr
	route := newPathRoute(msg.route, msg.routeErr)
	pm.route = &route
	if !msg.source.isHost() {
		c := newPathContainer(msg.source, msg.ctr, msg.ctrErr).withBridgeRead(msg.bridge)
		pm.container = &c
	}
	pm.refreshSteps()
	return pm, waitForPathMsg(pm.msgs)
}

func (pm *PathModel) handleHop(msg pathHopMsg) (*PathModel, tea.Cmd) {
	if msg.gen != pm.gen {
		return pm, nil
	}
	pm.hops = append(pm.hops, msg.hop)
	pm.refreshSteps()
	return pm, waitForPathMsg(pm.msgs)
}

func (pm *PathModel) handleDone(msg pathDoneMsg) (*PathModel, tea.Cmd) {
	if msg.gen != pm.gen {
		return pm, nil
	}
	pm.releaseRun()
	if msg.err != nil {
		pm.hops = nil
		pm.route = nil
		pm.container = nil
		pm.table.SetItems(nil)
		pm.errText = pathErrorLabel(pm.target.Host, msg.err)
		pm.state = pathEditing
		return pm, pm.input.Focus()
	}
	res := msg.result
	pm.result = &res
	pm.hops = res.Hops
	pm.refreshSteps()
	pm.state = pathDone
	return pm, nil
}

// refreshSteps rebuilds the table rows from the route and the hops.
func (pm *PathModel) refreshSteps() { pm.table.SetItems(pathSteps(pm.container, pm.route, pm.hops)) }

// clearRun forgets what the last run put on screen: the resolved address, the
// route, the container, the hops, the outcome and the error.
func (pm *PathModel) clearRun() {
	pm.addr = netip.Addr{}
	pm.hops = nil
	pm.route = nil
	pm.container = nil
	pm.result = nil
	pm.errText = ""
	pm.table.SetItems(nil)
}

// hopCount is the number of hop rows (the local rows are not counted).
func (pm *PathModel) hopCount() int {
	n := 0
	for _, s := range pm.table.Items() {
		if s.Kind == stepHop {
			n++
		}
	}
	return n
}

// releaseRun cancels the run's context (releasing it) and forgets its channel.
func (pm *PathModel) releaseRun() {
	if pm.cancel != nil {
		pm.cancel()
		pm.cancel = nil
	}
	pm.msgs = nil
}

func isPathNavKey(key string) bool {
	switch key {
	case "up", "down", "pgup", "pgdown", "home", "end":
		return true
	}
	return false
}

func (pm *PathModel) handleKey(msg tea.KeyPressMsg) (*PathModel, tea.Cmd) {
	key := msg.String()
	if pm.pickerOpen() {
		return pm.handlePickerKey(key)
	}
	if key == pathSourceKey {
		return pm.openPicker()
	}
	if isPathNavKey(key) {
		return pm, pm.table.Update(msg)
	}
	switch pm.state {
	case pathEditing:
		return pm.handleEditKey(msg)
	case pathRunning:
		if key == "esc" {
			return pm.cancelRun()
		}
	case pathDone:
		switch key {
		case "enter":
			return pm.launch(pm.target)
		case "esc":
			pm.state = pathEditing
			return pm, pm.input.Focus()
		}
	}
	return pm, nil
}

func (pm *PathModel) handleEditKey(msg tea.KeyPressMsg) (*PathModel, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return pm.launchFromInput()
	case "esc", "tab", "shift+tab":
		return pm, nil
	}
	return pm.updateInput(msg)
}

func (pm *PathModel) handlePaste(msg tea.PasteMsg) (*PathModel, tea.Cmd) {
	if pm.state != pathEditing || pm.pickerOpen() {
		return pm, nil // a paste reaches the focused field only (Rule 111)
	}
	return pm.updateInput(msg)
}

// updateInput hands msg to the field; a changed value drops the stale error.
func (pm *PathModel) updateInput(msg tea.Msg) (*PathModel, tea.Cmd) {
	before := pm.input.Value()
	var cmd tea.Cmd
	pm.input, cmd = pm.input.Update(msg)
	if pm.input.Value() != before {
		pm.errText = ""
	}
	return pm, cmd
}

func (pm *PathModel) launchFromInput() (*PathModel, tea.Cmd) {
	tg, err := parsePathTarget(pm.input.Value())
	if err != nil {
		return pm, pm.footer.Error(capitalize(err.Error()))
	}
	return pm.launch(tg)
}

// launch starts a run: the model changes here, in Update; the Cmd only does I/O.
func (pm *PathModel) launch(tg pathTarget) (*PathModel, tea.Cmd) {
	if a := pm.launchable(); !a.Enabled() {
		return pm, pm.footer.Warn(a.Reason)
	}
	pm.releaseRun()
	pm.gen++
	pm.target = tg
	pm.clearRun()
	pm.footer.Clear()

	ctx, cancel := context.WithCancel(context.Background())
	ch := make(chan tea.Msg, pathChanCap)
	pm.cancel, pm.msgs = cancel, ch
	pm.input.Blur()
	pm.state = pathRunning
	return pm, startPathRun(ctx, pm.gen, tg, pm.source, pm.resolveTimeout, pm.engine, ch)
}

// cancelRun answers esc at once: the run's late messages are dropped by the
// generation bump, the hops already seen stay on screen.
func (pm *PathModel) cancelRun() (*PathModel, tea.Cmd) {
	pm.releaseRun()
	pm.gen++
	pm.result = &nettrace.Result{Outcome: nettrace.OutcomeCancelled}
	pm.state = pathDone
	return pm, nil
}

// startPathRun builds the launch Cmd from values only, so that no closure
// reads the model (Rule 110).
func startPathRun(ctx context.Context, gen int, tg pathTarget, src pathSource, timeout time.Duration, e pathEngine, ch chan tea.Msg) tea.Cmd {
	return tea.Batch(
		func() tea.Msg {
			producePath(ctx, gen, tg, src, timeout, e, ch)
			return nil
		},
		waitForPathMsg(ch),
	)
}

